document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("health-check-form"),n=document.getElementById("health-check-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t={cashFlow:parseInt(document.getElementById("cash-flow").value)||0,profitMargin:parseInt(document.getElementById("profit-margin").value)||0,expenseManagement:parseInt(document.getElementById("expense-management").value)||0,processEfficiency:parseInt(document.getElementById("process-efficiency").value)||0,inventoryManagement:parseInt(document.getElementById("inventory-management").value)||0,technologyUsage:parseInt(document.getElementById("technology-usage").value)||0,customerRetention:parseInt(document.getElementById("customer-retention").value)||0,marketingEffectiveness:parseInt(document.getElementById("marketing-effectiveness").value)||0,digitalPresence:parseInt(document.getElementById("digital-presence").value)||0,businessGoals:parseInt(document.getElementById("business-goals").value)||0,growthPotential:parseInt(document.getElementById("growth-potential").value)||0,competitiveAnalysis:parseInt(document.getElementById("competitive-analysis").value)||0,teamProductivity:parseInt(document.getElementById("team-productivity").value)||0,leadershipEffectiveness:parseInt(document.getElementById("leadership-effectiveness").value)||0,riskPreparedness:parseInt(document.getElementById("risk-preparedness").value)||0,diversification:parseInt(document.getElementById("diversification").value)||0};if(Object.values(t).some(e=>0===e))return n.innerHTML='\n          <div class="insight-card warning">\n            <h6>⚠️ Incomplete Assessment</h6>\n            <p>Please answer all questions to get an accurate business health score.</p>\n          </div>\n        ',void 0;const s={financial:(t.cashFlow+t.profitMargin+t.expenseManagement)/3,operations:(t.processEfficiency+t.inventoryManagement+t.technologyUsage)/3,marketing:(t.customerRetention+t.marketingEffectiveness+t.digitalPresence)/3,growth:(t.businessGoals+t.growthPotential+t.competitiveAnalysis)/3,team:(t.teamProductivity+t.leadershipEffectiveness)/2,risk:(t.riskPreparedness+t.diversification)/2},i=Object.values(s).reduce((e,n)=>e+n,0),a=Math.round(i/6*10),r=(o=a)>=90?"Excellent":o>=80?"Good":o>=70?"Fair":o>=60?"Needs Attention":"Critical";var o;const c=function(e){return e>=90?"success":e>=80?"info":(e>=70,"warning")}(a),d=function(e){const n=[];return e.financial<7&&n.push("💰 <strong>Financial Health:</strong> Focus on improving cash flow management and expense tracking. Consider implementing better budgeting tools and financial controls."),e.operations<7&&n.push("⚙️ <strong>Operations:</strong> Streamline your processes and consider automation opportunities. Invest in technology to improve efficiency and reduce manual work."),e.marketing<7&&n.push("📈 <strong>Marketing:</strong> Develop a comprehensive marketing strategy. Focus on customer retention and building a stronger online presence."),e.growth<7&&n.push("🚀 <strong>Growth Strategy:</strong> Define clear, measurable business goals and develop actionable plans. Conduct thorough competitive analysis to identify opportunities."),e.team<7&&n.push("👥 <strong>Team & Leadership:</strong> Invest in team development and improve leadership skills. Focus on communication and productivity enhancement."),e.risk<7&&n.push("🛡️ <strong>Risk Management:</strong> Develop contingency plans and diversify revenue streams. Create comprehensive risk management strategies."),0===n.length&&n.push("🎉 <strong>Excellent Performance:</strong> Your business shows strong health across all areas. Focus on maintaining this performance and identifying new growth opportunities."),n}(s);n.innerHTML=`\n        <div class="insight-cards">\n          <div class="insight-card ${c}">\n            <h6>🏆 Overall Business Health Score</h6>\n            <div class="big-number">${a}/100</div>\n            <p><strong>${r}</strong></p>\n          </div>\n        </div>\n\n        <div class="insight-cards">\n          <div class="insight-card">\n            <h6>💰 Financial Health</h6>\n            <div class="big-number">${Math.round(10*s.financial)}/100</div>\n            <p>Cash flow, profitability & expense management</p>\n          </div>\n          <div class="insight-card">\n            <h6>⚙️ Operations</h6>\n            <div class="big-number">${Math.round(10*s.operations)}/100</div>\n            <p>Process efficiency & technology usage</p>\n          </div>\n          <div class="insight-card">\n            <h6>📈 Marketing</h6>\n            <div class="big-number">${Math.round(10*s.marketing)}/100</div>\n            <p>Customer relations & digital presence</p>\n          </div>\n        </div>\n\n        <div class="insight-cards">\n          <div class="insight-card">\n            <h6>🚀 Growth Strategy</h6>\n            <div class="big-number">${Math.round(10*s.growth)}/100</div>\n            <p>Goal setting & competitive positioning</p>\n          </div>\n          <div class="insight-card">\n            <h6>👥 Team & Leadership</h6>\n            <div class="big-number">${Math.round(10*s.team)}/100</div>\n            <p>Team productivity & leadership effectiveness</p>\n          </div>\n          <div class="insight-card">\n            <h6>🛡️ Risk Management</h6>\n            <div class="big-number">${Math.round(10*s.risk)}/100</div>\n            <p>Risk preparedness & diversification</p>\n          </div>\n        </div>\n\n        <div class="insight-card info">\n          <h6>📋 Key Recommendations</h6>\n          <ul style="text-align: left; margin: 1rem 0;">\n            ${d.map(e=>`<li>${e}</li>`).join("")}\n          </ul>\n        </div>\n\n        <div class="insight-card">\n          <h6>📊 Score Interpretation</h6>\n          <div style="text-align: left; font-size: 0.9rem;">\n            <p><strong>90-100:</strong> Excellent - Strong business with sustainable growth</p>\n            <p><strong>80-89:</strong> Good - Solid foundation with optimization opportunities</p>\n            <p><strong>70-79:</strong> Fair - Average performance, improvement needed</p>\n            <p><strong>60-69:</strong> Needs Attention - Significant issues requiring action</p>\n            <p><strong>Below 60:</strong> Critical - Immediate intervention required</p>\n          </div>\n        </div>\n\n        <div class="insight-card warning">\n          <h6>💡 Next Steps</h6>\n          <div style="text-align: left;">\n            <p>1. <strong>Focus on lowest-scoring areas</strong> - These represent your biggest risks</p>\n            <p>2. <strong>Create action plans</strong> - Set specific, measurable improvement goals</p>\n            <p>3. <strong>Monitor progress</strong> - Retake this assessment quarterly</p>\n            <p>4. <strong>Seek expert advice</strong> - Consult professionals for complex issues</p>\n          </div>\n        </div>\n      `})});